//! This crate provides unsafe Rust bindings for the parallel multi-terminal binary decision
//! diagram library [Sylvan](https://github.com/trolando/sylvan), currently based on Sylvan
//! `1.11.0` and its work-stealing framework [Lace](https://github.com/trolando/lace). Both
//! libraries are bundled with the crate and compiled using the `cc` crate, so only a C compiler
//! (and `libclang`, for `bindgen`) is required. For documentation, see the original source code
//! and the [tutorial](https://trolando.github.io/sylvan/).
//!
//! The bindings are generated by `bindgen` and use the same names as the C API. Sylvan defines
//! many operations as macros, which are ported to Rust functions with the same name and
//! arguments, i.e., `sylvan_and(a, b)` works exactly as in C.
//!
//! **Lace workers:** all Sylvan operations must be executed inside a Lace worker. Use
//! [`lace_run_callback`] to run a callback inside a worker:
//!
//! ```no_run
//! use sylvan_sys::*;
//! use std::ffi::c_void;
//!
//! unsafe extern "C" fn run(_context: *mut c_void) {
//!     unsafe {
//!         let a = sylvan_ithvar(1);
//!         let b = sylvan_ithvar(2);
//!         let _a_and_b = sylvan_and(a, b);
//!     }
//! }
//!
//! unsafe {
//!     lace_start(0, 0); // auto-detect the number of workers
//!     sylvan_set_limits(1 << 26, 1, 5);
//!     sylvan_init_package();
//!     sylvan_init_bdd();
//!     lace_run_callback(Some(run), std::ptr::null_mut());
//!     sylvan_quit();
//!     lace_stop();
//! }
//! ```

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::missing_safety_doc)]

mod bindings {
    #![allow(unnecessary_transmutes, clippy::all)]
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

mod macros;

pub use bindings::*;
pub use macros::*;

#[cfg(test)]
mod test;

// These are `static const` or `#define` in the headers, so they are not exported by bindgen.

pub const mtbdd_complement: MTBDD = 0x8000000000000000;
pub const mtbdd_false: MTBDD = 0;
pub const mtbdd_true: MTBDD = 0x8000000000000000;
pub const mtbdd_invalid: MTBDD = u64::MAX;

pub const sylvan_complement: MTBDD = mtbdd_complement;
pub const sylvan_false: MTBDD = mtbdd_false;
pub const sylvan_true: MTBDD = mtbdd_true;
pub const sylvan_invalid: MTBDD = mtbdd_invalid;

pub const zdd_complement: ZDD = 0x8000000000000000;
pub const zdd_false: ZDD = 0;
/// Sylvan is compiled with `ZDD_COMPLEMENT_EDGES` enabled.
pub const zdd_true: ZDD = 0x8000000000000000;
pub const zdd_invalid: ZDD = u64::MAX;

// Macros that are not translated by `tools/generate_macros.py`.

/// Rust version of the C macro `mtbdd_leafcount(dd)`.
#[inline]
pub unsafe fn mtbdd_leafcount(dd: MTBDD) -> usize {
    unsafe { mtbdd_leafcount_more(&dd, 1) }
}

/// Rust version of the C macro `zdd_isnode(dd)`.
#[inline]
pub unsafe fn zdd_isnode(dd: ZDD) -> i32 {
    unsafe { if zdd_isleaf(dd) != 0 { 0 } else { 1 } }
}

/// Rust version of the C macro `zdd_set_empty()`.
#[inline]
pub fn zdd_set_empty() -> ZDD {
    zdd_true
}

/// Rust version of the C macro `zdd_set_isempty(set)`.
#[inline]
pub fn zdd_set_isempty(set: ZDD) -> bool {
    set == zdd_true
}

/// Rust version of the C macro `zdd_set_from_mtbdd(orig)`.
#[inline]
pub unsafe fn zdd_set_from_mtbdd(orig: MTBDD) -> ZDD {
    unsafe { zdd_from_mtbdd(sylvan_true, orig) }
}

/// Rust version of the C macro `zdd_map_empty()`.
#[inline]
pub fn zdd_map_empty() -> ZDD {
    zdd_false
}

/// Rust version of the C macro `zdd_map_isempty(map)`.
#[inline]
pub fn zdd_map_isempty(map: ZDD) -> i32 {
    if map == zdd_false { 1 } else { 0 }
}
